// Extract fields from Telegram update, apply security whitelist
const allowedIds = ($env.ALLOWED_CHAT_IDS || '').split(',').map(s => s.trim()).filter(Boolean);
const update = $input.first().json;

let chatId, text, photos, callbackData, callbackQueryId, updateId, messageId;
photos = [];

if (update.message) {
  chatId = String(update.message.chat.id);
  messageId = update.message.message_id;
  text = update.message.text || update.message.caption || '';
  photos = update.message.photo || [];
} else if (update.callback_query) {
  chatId = String(update.callback_query.message.chat.id);
  messageId = update.callback_query.message.message_id;
  callbackData = update.callback_query.data || '';
  callbackQueryId = update.callback_query.id;
  text = '';
} else {
  return [{json: {allowed: false, chatId: '', updateId: 0}}];
}

updateId = update.update_id;
const allowed = allowedIds.includes(chatId);

return [{
  json: {
    allowed,
    updateId,
    chatId,
    messageId,
    text: text || '',
    photos,
    callbackData: callbackData || '',
    callbackQueryId: callbackQueryId || '',
    isCallback: !!update.callback_query,
    isMessage: !!update.message
  }
}];

// Merge session data + check TTL + run state machine
const extracted = $('Code: Extract').first().json;
const sessionRows = $input.all();

const {chatId, text, photos, callbackData, callbackQueryId, isCallback, isMessage, updateId} = extracted;

// Dedup via Static Data
const staticData = $getWorkflowStaticData('global');
if (!staticData.processedIds) staticData.processedIds = {};
if (staticData.processedIds[updateId]) {
  return [{json: {nextAction: 'noop', chatId, updateId}}];
}
// Cleanup old IDs (>24h)
const DAY = 86400000;
for (const [id, ts] of Object.entries(staticData.processedIds)) {
  if (Date.now() - ts > DAY) delete staticData.processedIds[id];
}
// Mark as processed immediately to prevent race conditions
staticData.processedIds[updateId] = Date.now();

// Parse session
let session = {state: '', type: '', draft_json: '{}', target_file: '', updated_at: ''};
const row = sessionRows.find(r => r.json && r.json.chat_id);
if (row && row.json.chat_id) {
  session = {
    state: row.json.state || '',
    type: row.json.type || '',
    draft_json: row.json.draft_json || '{}',
    target_file: row.json.target_file || '',
    updated_at: row.json.updated_at || ''
  };
}

// Check TTL 30 min
if (session.updated_at && session.state) {
  const lastActive = new Date(session.updated_at).getTime();
  if (Date.now() - lastActive > 1800000) {
    session = {state: '', type: '', draft_json: '{}', target_file: '', updated_at: ''};
    return [{json: {
      nextAction: 'send_message', chatId, updateId,
      text: '⏰ Phiên làm việc đã hết hạn. Anh gõ /menu để bắt đầu lại.',
      session: {state: '', type: '', draft_json: '{}', target_file: '', updated_at: ''},
      sessionAction: 'clear'
    }}];
  }
}

// Parse command
let command = '';
if (isMessage && text && text.trim().startsWith('/')) {
  command = text.trim().split(/\s+/)[0].toLowerCase().split('@')[0];
}

// /huy always resets
if (command === '/huy' || command === '/cancel') {
  return [{json: {
    nextAction: 'send_message', chatId, updateId,
    text: '❌ Đã huỷ.',
    session: {state: '', type: '', draft_json: '{}', target_file: '', updated_at: ''},
    sessionAction: 'clear'
  }}];
}

const state = session.state;
const now = new Date().toISOString();

// --- IDLE STATE ---
if (!state) {
  if (command === '/them' || command === '/start_them') {
    return [{json: {
      nextAction: 'send_message', chatId, updateId,
      text: '📋 Anh muốn thêm gì?',
      keyboard: {inline_keyboard: [[{text: '📦 Dự án', callback_data: 'them_type:project'},{text: '📝 Bài viết', callback_data: 'them_type:article'}]]},
      session: {state: 'awaiting_type', type: '', draft_json: '{}', target_file: '', updated_at: now},
      sessionAction: 'write'
    }}];
  }
  if (command === '/sua') {
    return [{json: {
      nextAction: 'send_message', chatId, updateId,
      text: '✏️ Anh muốn sửa loại nội dung nào?',
      keyboard: {inline_keyboard: [[{text: '📦 Dự án', callback_data: 'sua_type:project'},{text: '📝 Bài viết', callback_data: 'sua_type:article'}]]},
      session: {state: 'sua:awaiting_type', type: '', draft_json: '{}', target_file: '', updated_at: now},
      sessionAction: 'write'
    }}];
  }
  if (command === '/xoa') {
    return [{json: {
      nextAction: 'send_message', chatId, updateId,
      text: '🗑️ Anh muốn xoá loại nội dung nào?',
      keyboard: {inline_keyboard: [[{text: '📦 Dự án', callback_data: 'xoa_type:project'},{text: '📝 Bài viết', callback_data: 'xoa_type:article'}]]},
      session: {state: 'xoa:awaiting_type', type: '', draft_json: '{}', target_file: '', updated_at: now},
      sessionAction: 'write'
    }}];
  }
  if (command === '/menu' || command === '/start') {
    return [{json: {
      nextAction: 'send_message', chatId, updateId,
      text: '🏠 *Menu chính 1992Land*\n\nChọn thao tác:',
      parseMode: 'Markdown',
      keyboard: {inline_keyboard: [[{text: '➕ Thêm', callback_data: 'menu:them'},{text: '✏️ Sửa', callback_data: 'menu:sua'},{text: '🗑️ Xoá', callback_data: 'menu:xoa'}]]},
      session: null, sessionAction: 'none'
    }}];
  }
  if (command === '/help') {
    return [{json: {
      nextAction: 'send_message', chatId, updateId,
      text: '📖 *1992Land Bot — Hướng dẫn*\n\n/them — Thêm dự án hoặc bài viết\n/sua — Sửa nội dung đã đăng\n/xoa — Xoá nội dung\n/menu — Menu chính\n/huy — Huỷ thao tác hiện tại',
      parseMode: 'Markdown',
      session: null, sessionAction: 'none'
    }}];
  }
  // Callback from menu shortcuts
  if (isCallback) {
    if (callbackData === 'menu:them') {
      return [{json: {
        nextAction: 'send_message', chatId, updateId, callbackQueryId,
        text: '📋 Anh muốn thêm gì?',
        keyboard: {inline_keyboard: [[{text: '📦 Dự án', callback_data: 'them_type:project'},{text: '📝 Bài viết', callback_data: 'them_type:article'}]]},
        session: {state: 'awaiting_type', type: '', draft_json: '{}', target_file: '', updated_at: now},
        sessionAction: 'write'
      }}];
    }
    if (callbackData === 'menu:sua') {
      return [{json: {
        nextAction: 'send_message', chatId, updateId, callbackQueryId,
        text: '✏️ Anh muốn sửa loại nội dung nào?',
        keyboard: {inline_keyboard: [[{text: '📦 Dự án', callback_data: 'sua_type:project'},{text: '📝 Bài viết', callback_data: 'sua_type:article'}]]},
        session: {state: 'sua:awaiting_type', type: '', draft_json: '{}', target_file: '', updated_at: now},
        sessionAction: 'write'
      }}];
    }
    if (callbackData === 'menu:xoa') {
      return [{json: {
        nextAction: 'send_message', chatId, updateId, callbackQueryId,
        text: '🗑️ Anh muốn xoá loại nội dung nào?',
        keyboard: {inline_keyboard: [[{text: '📦 Dự án', callback_data: 'xoa_type:project'},{text: '📝 Bài viết', callback_data: 'xoa_type:article'}]]},
        session: {state: 'xoa:awaiting_type', type: '', draft_json: '{}', target_file: '', updated_at: now},
        sessionAction: 'write'
      }}];
    }
  }
  // Unknown
  if (command) {
    return [{json: {nextAction: 'send_message', chatId, updateId, text: '🤔 Em chưa hiểu lệnh đó. Anh gõ /menu nhé.', session: null, sessionAction: 'none'}}];
  }
  return [{json: {nextAction: 'send_message', chatId, updateId, text: '💬 Anh gõ /menu để xem menu chính nhé.', session: null, sessionAction: 'none'}}];
}

// --- AWAITING_TYPE ---
if (state === 'awaiting_type' && isCallback) {
  if (callbackData.startsWith('them_type:')) {
    const t = callbackData.split(':')[1];
    const prompt = t === 'project'
      ? '📦 Anh kể em nghe về dự án — cứ tự nhiên, không cần theo format.\n\nVí dụ: "Vinhomes Ocean Park 3 ở Gia Lâm HN, giá 2 tỷ, mở bán Q2/2026, CĐT Vinhomes"\n\nCó ảnh đại diện thì gửi luôn nhé 📸'
      : '📝 Anh gửi nội dung bài viết — cứ viết tự nhiên.\n\nNếu có ảnh bìa thì gửi kèm nhé.';
    return [{json: {
      nextAction: 'send_message', chatId, updateId, callbackQueryId,
      text: prompt,
      session: {state: 'awaiting_content', type: t, draft_json: '{}', target_file: '', updated_at: now},
      sessionAction: 'write'
    }}];
  }
}

// --- AWAITING_CONTENT ---
if (state === 'awaiting_content' && isMessage) {
  const largestPhoto = photos.length > 0 ? photos[photos.length - 1] : null;
  return [{json: {
    nextAction: 'parse_with_ai', chatId, updateId,
    contentType: session.type,
    userText: text,
    photo: largestPhoto,
    session: {...session, updated_at: now},
    sessionAction: 'write'
  }}];
}

// --- REVIEW STATE ---
if (state === 'review' && isCallback) {
  let draft;
  try { draft = JSON.parse(session.draft_json || '{}'); } catch(e) { draft = {}; }

  if (callbackData === 'action:confirm') {
    return [{json: {
      nextAction: 'commit_to_github', chatId, updateId, callbackQueryId,
      contentType: session.type,
      draft,
      targetFile: session.target_file,
      isEdit: !!session.target_file,
      session: null, sessionAction: 'clear'
    }}];
  }
  if (callbackData === 'action:cancel') {
    return [{json: {
      nextAction: 'send_message', chatId, updateId, callbackQueryId,
      text: '❌ Đã huỷ.',
      session: null, sessionAction: 'clear'
    }}];
  }
  if (callbackData === 'action:edit') {
    const fieldButtons = session.type === 'project' ? [
      [{text: 'Tên', callback_data: 'edit_field:title'},{text: 'Vị trí', callback_data: 'edit_field:location'}],
      [{text: 'Chủ đầu tư', callback_data: 'edit_field:developer'},{text: 'Giá', callback_data: 'edit_field:priceRange'}],
      [{text: 'Trạng thái', callback_data: 'edit_field:status'},{text: 'Loại', callback_data: 'edit_field:type'}],
      [{text: 'Khu vực', callback_data: 'edit_field:area'},{text: 'Mô tả', callback_data: 'edit_field:excerpt'}],
      [{text: '❌ Huỷ', callback_data: 'action:cancel'}]
    ] : [
      [{text: 'Tiêu đề', callback_data: 'edit_field:title'},{text: 'Mô tả ngắn', callback_data: 'edit_field:excerpt'}],
      [{text: 'Danh mục', callback_data: 'edit_field:category'},{text: 'Nội dung', callback_data: 'edit_field:body'}],
      [{text: '❌ Huỷ', callback_data: 'action:cancel'}]
    ];
    return [{json: {
      nextAction: 'send_message', chatId, updateId, callbackQueryId,
      text: '✏️ Sửa field nào?',
      keyboard: {inline_keyboard: fieldButtons},
      session: {...session, state: 'choose_field', updated_at: now},
      sessionAction: 'write'
    }}];
  }
}

// --- CHOOSE_FIELD ---
if (state === 'choose_field' && isCallback && callbackData.startsWith('edit_field:')) {
  const fieldName = callbackData.split(':')[1];
  const labels = {title:'Tên/Tiêu đề',location:'Vị trí',developer:'Chủ đầu tư',priceRange:'Giá',status:'Trạng thái',type:'Loại',area:'Khu vực',excerpt:'Mô tả ngắn',body:'Nội dung',category:'Danh mục'};
  let draft;
  try { draft = JSON.parse(session.draft_json || '{}'); } catch(e) { draft = {}; }
  const currentVal = draft[fieldName] || '(trống)';
  return [{json: {
    nextAction: 'send_message', chatId, updateId, callbackQueryId,
    text: `✏️ *${labels[fieldName]||fieldName}* hiện tại:\n${currentVal.toString().slice(0,200)}\n\nAnh nhập giá trị mới:`,
    parseMode: 'Markdown',
    session: {...session, state: `editing_field:${fieldName}`, updated_at: now},
    sessionAction: 'write'
  }}];
}

// --- EDITING_FIELD ---
if (state && state.startsWith('editing_field:') && isMessage && text) {
  const fieldName = state.replace('editing_field:', '');
  let draft;
  try { draft = JSON.parse(session.draft_json || '{}'); } catch(e) { draft = {}; }
  draft[fieldName] = text.trim();
  return [{json: {
    nextAction: 'show_review', chatId, updateId,
    contentType: session.type,
    draft,
    session: {...session, state: 'review', draft_json: JSON.stringify(draft), updated_at: now},
    sessionAction: 'write'
  }}];
}

// --- SUA: awaiting_type ---
if (state === 'sua:awaiting_type' && isCallback && callbackData.startsWith('sua_type:')) {
  const t = callbackData.split(':')[1];
  return [{json: {
    nextAction: 'fetch_github_list', chatId, updateId, callbackQueryId,
    contentType: t, flowMode: 'sua',
    session: {state: 'sua:list', type: t, draft_json: '{}', target_file: '', updated_at: now},
    sessionAction: 'write'
  }}];
}

// --- XOA: awaiting_type ---
if (state === 'xoa:awaiting_type' && isCallback && callbackData.startsWith('xoa_type:')) {
  const t = callbackData.split(':')[1];
  return [{json: {
    nextAction: 'fetch_github_list', chatId, updateId, callbackQueryId,
    contentType: t, flowMode: 'xoa',
    session: {state: 'xoa:list', type: t, draft_json: '{}', target_file: '', updated_at: now},
    sessionAction: 'write'
  }}];
}

// --- SUA/XOA: list ---
if ((state === 'sua:list' || state === 'xoa:list') && isCallback && callbackData.startsWith('select:')) {
  const slug = callbackData.replace('select:', '');
  const flowMode = state.startsWith('sua') ? 'sua' : 'xoa';
  if (flowMode === 'sua') {
    return [{json: {
      nextAction: 'fetch_github_file', chatId, updateId, callbackQueryId,
      slug, contentType: session.type,
      session: {...session, state: 'review', target_file: slug, updated_at: now},
      sessionAction: 'write'
    }}];
  } else {
    return [{json: {
      nextAction: 'send_message', chatId, updateId, callbackQueryId,
      text: `⚠️ Xác nhận xoá *${slug}*?\n\nHành động này không thể hoàn tác.`,
      parseMode: 'Markdown',
      keyboard: {inline_keyboard: [[{text: '🗑️ Xoá', callback_data: `confirm_delete:${slug}`},{text: '❌ Không', callback_data: 'action:cancel'}]]},
      session: {...session, state: 'xoa:confirm', target_file: slug, updated_at: now},
      sessionAction: 'write'
    }}];
  }
}

// --- XOA: confirm ---
if (state === 'xoa:confirm' && isCallback) {
  if (callbackData.startsWith('confirm_delete:')) {
    const slug = callbackData.replace('confirm_delete:', '');
    return [{json: {
      nextAction: 'delete_from_github', chatId, updateId, callbackQueryId,
      slug, contentType: session.type,
      session: null, sessionAction: 'clear'
    }}];
  }
  if (callbackData === 'action:cancel') {
    return [{json: {
      nextAction: 'send_message', chatId, updateId, callbackQueryId,
      text: '❌ Đã huỷ.',
      session: null, sessionAction: 'clear'
    }}];
  }
}

// --- Fallback ---
return [{json: {
  nextAction: 'send_message', chatId, updateId,
  text: '💬 Anh gõ /menu để xem menu chính nhé.',
  session: null, sessionAction: 'none'
}}];

// Prepare Claude API call — build prompt, handle photo
const d = $input.first().json;
const {contentType, userText, photo, chatId} = d;

let systemPrompt, userPrompt;

if (contentType === 'project') {
  systemPrompt = `Bạn là parser cho bot quản lý nội dung BĐS Việt Nam.
Nhiệm vụ: Đọc tin nhắn tự nhiên, trích xuất thành JSON theo schema sau.

SCHEMA (bắt buộc khớp 100%, không thêm field lạ):
{
  "title": string,        // tên dự án, BẮT BUỘC
  "location": string,     // vị trí, ví dụ "Quận 7, TP.HCM", BẮT BUỘC
  "area": string,         // tỉnh/thành phố, ví dụ "TP.HCM", BẮT BUỘC
  "developer": string,    // chủ đầu tư, BẮT BUỘC
  "priceRange": string,   // giá, format "Từ X tỷ/căn" hoặc "Liên hệ", BẮT BUỘC
  "status": string,       // một trong: "Đang mở bán"|"Sắp mở bán"|"Đã bàn giao", BẮT BUỘC
  "type": string,         // loại hình, ví dụ "Căn hộ chung cư"|"Biệt thự"|"Nhà phố", BẮT BUỘC
  "excerpt": string,      // mô tả SEO 2-3 câu, AI TỰ VIẾT nếu user không cung cấp
  "project_type": string, // slug: "can-ho"|"biet-thu"|"dat-nen"|"nha-pho"|"nghi-duong"|"phuc-hop"
  "city": string          // slug: "tp-hcm"|"vung-tau"|"binh-duong"|"long-an"|"dong-nai"
}

QUY TẮC NGHIÊM NGẶT:
- KHÔNG bịa giá, vị trí, chủ đầu tư, trạng thái pháp lý — nếu user không nói rõ → trả null
- "excerpt" ĐƯỢC PHÉP AI tự viết từ các field còn lại
- Chỉ trả JSON thuần, không markdown fence, không giải thích
- Slug hóa: TP.HCM→tp-hcm, Hà Nội→ha-noi, Vũng Tàu→vung-tau, Bình Dương→binh-duong, Long An→long-an, Đồng Nai→dong-nai`;
  userPrompt = `Tin nhắn của user:
${userText || '(không có text)'}`;
} else {
  systemPrompt = `Bạn là parser bài viết BĐS.
Trả về JSON:
{
  "title": string,    // tiêu đề, AI đặt từ nội dung nếu user không có
  "excerpt": string,  // 1-2 câu tóm tắt SEO
  "category": string, // ví dụ "Đầu tư"|"Kinh nghiệm"|"Thị trường"
  "readTime": string, // ước tính đọc, ví dụ "5 phút đọc"
  "body": string      // toàn bộ nội dung, format Markdown sạch
}
KHÔNG bịa thông tin. Chỉ trả JSON thuần.`;
  userPrompt = `Nội dung bài viết:
${userText || '(không có text)'}`;
}

return [{
  json: {
    ...d,
    claudePayload: {
      model: $env.ANTHROPIC_MODEL || 'claude-haiku-4-5-20251001',
      max_tokens: 1024,
      system: systemPrompt,
      messages: [{role: 'user', content: userPrompt}]
    },
    hasPhoto: !!photo,
    photoFileId: photo ? photo.file_id : null
  }
}];

// Validate Claude response, build review message
const prev = $('Code: Prep AI').first().json;
const claudeResp = $input.first().json;

let rawText = '';
try {
  rawText = claudeResp.content[0].text;
} catch(e) {
  return [{json: {
    nextAction: 'send_message',
    chatId: prev.chatId, updateId: prev.updateId,
    text: '❌ AI gặp lỗi. Anh thử lại hoặc gõ /huy.',
    session: null, sessionAction: 'none'
  }}];
}

// Strip markdown fence if any
rawText = rawText.replace(/^```json?\n?/,'').replace(/\n?```$/,'').trim();

let parsed;
try { parsed = JSON.parse(rawText); } catch(e) {
  return [{json: {
    nextAction: 'send_message',
    chatId: prev.chatId, updateId: prev.updateId,
    text: '❌ AI trả kết quả không đúng định dạng. Anh thử gõ lại rõ hơn hoặc /huy.',
    session: null, sessionAction: 'none'
  }}];
}

const contentType = prev.contentType;

// Build review message
let reviewLines = ['📋 *Em hiểu thế này, anh xem giúp:*\n'];
if (contentType === 'project') {
  const fields = [
    ['Tên', parsed.title],
    ['Vị trí', parsed.location],
    ['Chủ đầu tư', parsed.developer],
    ['Giá', parsed.priceRange],
    ['Trạng thái', parsed.status],
    ['Loại', parsed.type],
    ['Khu vực', parsed.area],
    ['Mô tả', parsed.excerpt ? parsed.excerpt.slice(0,100)+'...' : null],
    ['Ảnh', prev.hasPhoto ? '✓ Có ảnh' : '✗ Không có ảnh']
  ];
  for (const [label, val] of fields) {
    reviewLines.push(`• *${label}:* ${val || '❓ Chưa có — bấm Sửa để điền'}`);
  }
} else {
  const fields = [
    ['Tiêu đề', parsed.title],
    ['Danh mục', parsed.category],
    ['Thời gian đọc', parsed.readTime],
    ['Mô tả ngắn', parsed.excerpt ? parsed.excerpt.slice(0,100) : null],
    ['Nội dung', parsed.body ? `${parsed.body.slice(0,80)}...` : null],
    ['Ảnh bìa', prev.hasPhoto ? '✓ Có ảnh' : '✗ Không có ảnh']
  ];
  for (const [label, val] of fields) {
    reviewLines.push(`• *${label}:* ${val || '❓ Chưa có — bấm Sửa để điền'}`);
  }
}

const reviewText = reviewLines.join('\n');
const keyboard = contentType === 'project'
  ? {inline_keyboard: [[{text:'✅ Đăng lên web',callback_data:'action:confirm'},{text:'✏️ Sửa',callback_data:'action:edit'},{text:'❌ Huỷ',callback_data:'action:cancel'}]]}
  : {inline_keyboard: [[{text:'✅ Đăng',callback_data:'action:confirm'},{text:'✏️ Sửa tiêu đề',callback_data:'edit_field:title'},{text:'❌ Huỷ',callback_data:'action:cancel'}]]};

return [{json: {
  nextAction: 'send_review_from_ai',
  chatId: prev.chatId, updateId: prev.updateId,
  text: reviewText,
  parseMode: 'Markdown',
  keyboard,
  parsedDraft: parsed,
  contentType,
  hasPhoto: prev.hasPhoto,
  photoData: prev.photoData || null,
  photoBinary: null,
  session: {
    state: 'review',
    type: contentType,
    draft_json: JSON.stringify(parsed),
    target_file: '',
    updated_at: new Date().toISOString()
  },
  sessionAction: 'write'
}}];

// Prepare GitHub commit payload using Git Trees API
const d = $input.first().json;
const {contentType, draft, targetFile, isEdit, chatId, updateId} = d;

const repo = $env.GITHUB_REPO;
const branch = $env.GITHUB_BRANCH || 'main';

// Generate slug
function slugify(text) {
  const map = {'à':'a','á':'a','ả':'a','ã':'a','ạ':'a','ă':'a','ắ':'a','ặ':'a','ẵ':'a','ằ':'a','ẳ':'a','â':'a','ấ':'a','ầ':'a','ẩ':'a','ẫ':'a','ậ':'a','đ':'d','è':'e','é':'e','ẻ':'e','ẽ':'e','ẹ':'e','ê':'e','ế':'e','ề':'e','ể':'e','ễ':'e','ệ':'e','ì':'i','í':'i','ỉ':'i','ĩ':'i','ị':'i','ò':'o','ó':'o','ỏ':'o','õ':'o','ọ':'o','ô':'o','ố':'o','ồ':'o','ổ':'o','ỗ':'o','ộ':'o','ơ':'o','ớ':'o','ờ':'o','ở':'o','ỡ':'o','ợ':'o','ù':'u','ú':'u','ủ':'u','ũ':'u','ụ':'u','ư':'u','ứ':'u','ừ':'u','ử':'u','ữ':'u','ự':'u','ỳ':'y','ý':'y','ỷ':'y','ỹ':'y','ỵ':'y'};
  return text.toLowerCase().split('').map(c => map[c] || c).join('').replace(/[^a-z0-9]+/g,'-').replace(/^-+|-+$/g,'');
}

let slug, filePath, fileContent;

if (isEdit && targetFile) {
  slug = targetFile;
} else {
  const base = slugify(draft.title || 'du-an');
  slug = `${base}-${Math.floor(Date.now()/1000)}`;
}

if (contentType === 'project') {
  const id = `prj_${slug.replace(/-/g,'_')}`;
  const projectJson = {
    order: 99,
    id,
    slug,
    title: draft.title || '',
    location: draft.location || '',
    area: draft.area || '',
    project_type: draft.project_type || 'can-ho',
    city: draft.city || 'tp-hcm',
    developer: draft.developer || '',
    priceRange: draft.priceRange || 'Liên hệ',
    price_from: null,
    price_to: null,
    status: draft.status || 'Đang mở bán',
    type: draft.type || '',
    excerpt: draft.excerpt || '',
    gradient: 'from-navy-900 to-navy-700',
    hero_image: d.hasPhoto ? `/images/projects/${slug}/hero.jpg` : '',
    gallery: d.hasPhoto ? [`/images/projects/${slug}/hero.jpg`] : [],
    location_image: '',
    amenities_images: [],
    legal_status: 'Liên hệ 1992 Land để cập nhật thông tin pháp lý.',
    created_at: new Date().toISOString(),
    updated_at: new Date().toISOString()
  };
  if (isEdit) {
    Object.assign(projectJson, draft);
    projectJson.updated_at = new Date().toISOString();
  }
  fileContent = JSON.stringify(projectJson, null, 2);
  filePath = `data/projects/${slug}.json`;
} else {
  const today = new Date().toISOString().slice(0,10);
  const frontmatter = [
    '---',
    `slug: ${slug}`,
    `title: "${(draft.title||'').replace(/"/g,'\\"')}"`,
    `date: ${today}`,
    `category: ${draft.category || 'Kiến thức'}`,
    `readTime: "${draft.readTime || '5 phút đọc'}"`,
    `excerpt: "${(draft.excerpt||'').replace(/"/g,'\\"')}"`,
    d.hasPhoto ? `hero_image: "/images/projects/${slug}/hero.jpg"` : '',
    '---'
  ].filter(Boolean).join('\n');
  fileContent = `${frontmatter}\n\n${draft.body || ''}\n`;
  filePath = `data/posts/${slug}.md`;
}

const treeItems = [
  {
    path: filePath,
    mode: '100644',
    type: 'blob',
    content: fileContent
  }
];

// Photo will be added by next nodes if hasPhoto
const commitMessage = isEdit
  ? `[bot] sửa ${contentType === 'project' ? 'dự án' : 'bài viết'}: ${draft.title || slug}`
  : `[bot] thêm ${contentType === 'project' ? 'dự án' : 'bài viết'}: ${draft.title || slug}`;

return [{json: {
  chatId, updateId,
  repo, branch,
  slug, filePath, contentType,
  treeItems,
  commitMessage,
  hasPhoto: d.hasPhoto,
  photoBinaryData: null,
  successUrl: contentType === 'project' ? `https://1992land.com/du-an/${slug}` : `https://1992land.com/blog/${slug}`
}}];

