// Format file list into Telegram inline keyboard
const brain = $('Code: State Machine').first().json;
const files = $input.first().json;

let fileList;
if (Array.isArray(files)) {
  fileList = files;
} else {
  return [{json: {
    nextAction: 'send_message',
    chatId: brain.chatId, updateId: brain.updateId,
    text: '❌ Không thể lấy danh sách. Anh thử lại sau.',
    session: null, sessionAction: 'none'
  }}];
}

// Sort by name desc (newest first typically), take top 5
const sorted = fileList.slice().sort((a,b) => b.name.localeCompare(a.name)).slice(0,5);

const buttons = sorted.map(f => {
  const slug = f.name.replace(/\.(json|md)$/, '');
  const label = slug.length > 30 ? slug.slice(0,30)+'…' : slug;
  return [{text: label, callback_data: `select:${slug}`}];
});
buttons.push([{text: '🔍 Tìm slug khác', callback_data: 'select_manual'}]);
buttons.push([{text: '❌ Huỷ', callback_data: 'action:cancel'}]);

const flowMode = brain.flowMode;
const typeLabel = brain.contentType === 'project' ? 'dự án' : 'bài viết';

return [{json: {
  nextAction: 'send_list',
  chatId: brain.chatId, updateId: brain.updateId, callbackQueryId: brain.callbackQueryId,
  text: `📋 Chọn ${typeLabel} muốn ${flowMode === 'sua' ? 'sửa' : 'xoá'}:`,
  keyboard: {inline_keyboard: buttons},
  session: brain.session, sessionAction: 'write'
}}];

// Parse fetched GitHub file into draft object
const brain = $('Code: State Machine').first().json;
const ghFile = $input.first().json;

let parsed;
try {
  const raw = Buffer.from(ghFile.content, 'base64').toString('utf8');
  if (brain.contentType === 'project') {
    parsed = JSON.parse(raw);
  } else {
    // Parse MD frontmatter
    const match = raw.match(/^---\r?\n([\s\S]*?)\r?\n---\r?\n?([\s\S]*)$/);
    if (match) {
      const meta = {};
      for (const line of match[1].split(/\r?\n/)) {
        const idx = line.indexOf(': ');
        if (idx > -1) {
          const k = line.slice(0,idx).trim();
          const v = line.slice(idx+2).trim().replace(/^"|"$/g,'');
          meta[k] = v;
        }
      }
      meta.body = match[2].trim();
      parsed = meta;
    } else {
      parsed = {body: raw};
    }
  }
} catch(e) {
  return [{json: {
    nextAction: 'send_message',
    chatId: brain.chatId, updateId: brain.updateId,
    text: '❌ Không đọc được file. Lỗi: ' + e.message,
    session: null, sessionAction: 'none'
  }}];
}

// Build review message
const lines = ['📋 *Nội dung hiện tại:*\n'];
const previewFields = brain.contentType === 'project'
  ? ['title','location','developer','priceRange','status','type','area','excerpt']
  : ['title','category','readTime','excerpt'];
for (const f of previewFields) {
  const v = parsed[f];
  lines.push(`• *${f}:* ${v ? String(v).slice(0,80) : '(trống)'}`);
}

const keyboard = {inline_keyboard: [
  [{text:'✅ Lưu không đổi', callback_data:'action:confirm'},{text:'✏️ Sửa field', callback_data:'action:edit'}],
  [{text:'❌ Huỷ', callback_data:'action:cancel'}]
]};

return [{json: {
  nextAction: 'send_review_from_edit',
  chatId: brain.chatId, updateId: brain.updateId,
  text: lines.join('\n'),
  parseMode: 'Markdown',
  keyboard,
  session: {
    state: 'review',
    type: brain.contentType,
    draft_json: JSON.stringify(parsed),
    target_file: brain.slug,
    updated_at: new Date().toISOString()
  },
  sessionAction: 'write'
}}];

// Prepare delete commit using GitHub Contents API
const d = $input.first().json;
const {slug, contentType, chatId, updateId} = d;
const repo = $env.GITHUB_REPO;
const branch = $env.GITHUB_BRANCH || 'main';
const ext = contentType === 'project' ? 'json' : 'md';
const dir = contentType === 'project' ? 'data/projects' : 'data/posts';
const filePath = `${dir}/${slug}.${ext}`;
const typeLabel = contentType === 'project' ? 'dự án' : 'bài viết';

return [{json: {
  chatId, updateId,
  repo, branch, slug, filePath, contentType, typeLabel,
  commitMessage: `[bot] xoá ${typeLabel}: ${slug}`
}}];

// Build review message for show_review action (after field edit)
const d = $input.first().json;
const {contentType, draft, chatId, updateId} = d;

const lines = ['📋 *Đã cập nhật, anh xem lại:*\n'];
if (contentType === 'project') {
  const fields = [['Tên',draft.title],['Vị trí',draft.location],['Chủ đầu tư',draft.developer],['Giá',draft.priceRange],['Trạng thái',draft.status],['Loại',draft.type],['Khu vực',draft.area],['Mô tả',draft.excerpt]];
  for (const [l,v] of fields) lines.push(`• *${l}:* ${v || '❓ Chưa có'}`);
} else {
  const fields = [['Tiêu đề',draft.title],['Danh mục',draft.category],['Thời gian đọc',draft.readTime],['Mô tả',draft.excerpt]];
  for (const [l,v] of fields) lines.push(`• *${l}:* ${v || '❓ Chưa có'}`);
}

const keyboard = {inline_keyboard: [[{text:'✅ Đăng lên web',callback_data:'action:confirm'},{text:'✏️ Sửa thêm',callback_data:'action:edit'},{text:'❌ Huỷ',callback_data:'action:cancel'}]]};

return [{json: {
  chatId, updateId,
  text: lines.join('\n'),
  parseMode: 'Markdown',
  keyboard,
  session: d.session, sessionAction: 'write'
}}];
